argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32DlgSubmit {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr hDlg, int id);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern bool SetWindowText(IntPtr hWnd, string text);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern IntPtr SetFocus(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool IsWindow(IntPtr hWnd);
}
"@
$script:dlg=[IntPtr]::Zero
$cb=[W32DlgSubmit+EnumWindowsProc]{
 param($h,$l)
 $tsb=New-Object System.Text.StringBuilder 128
 $csb=New-Object System.Text.StringBuilder 64
 [void][W32DlgSubmit]::GetWindowText($h,$tsb,$tsb.Capacity)
 [void][W32DlgSubmit]::GetClassName($h,$csb,$csb.Capacity)
 if($tsb.ToString() -eq '開啟' -and $csb.ToString() -eq '#32770'){
   $script:dlg=$h
   return $false
 }
 return $true
}
[W32DlgSubmit]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
if($script:dlg -eq [IntPtr]::Zero){throw 'Open dialog not found'}

$file=[W32DlgSubmit]::GetDlgItem($script:dlg,1148)
$okBtn=[W32DlgSubmit]::GetDlgItem($script:dlg,1)
if($file -eq [IntPtr]::Zero){throw 'file control 1148 missing'}
if($okBtn -eq [IntPtr]::Zero){throw 'IDOK button missing'}

$path='C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg'
if(-not (Test-Path -LiteralPath $path)){throw 'confirmed image path missing'}
[W32DlgSubmit]::SetWindowText($file,$path)|Out-Null
$sb=New-Object System.Text.StringBuilder 1024
[void][W32DlgSubmit]::GetWindowText($file,$sb,$sb.Capacity)
$current=$sb.ToString()
if($current -ne $path){throw ('file field mismatch: '+$current)}

[W32DlgSubmit]::SetForegroundWindow($script:dlg)|Out-Null
[W32DlgSubmit]::SetFocus($file)|Out-Null
Start-Sleep -Milliseconds 200
# WM_COMMAND / IDOK is the canonical submit path for a common Open dialog.
[void][W32DlgSubmit]::SendMessage($script:dlg,0x0111,[IntPtr]1,$okBtn)
Start-Sleep -Seconds 2
if([W32DlgSubmit]::IsWindow($script:dlg)){
  [void][W32DlgSubmit]::PostMessage($script:dlg,0x0111,[IntPtr]1,$okBtn)
  Start-Sleep -Seconds 2
}
if([W32DlgSubmit]::IsWindow($script:dlg)){
  [W32DlgSubmit]::SetForegroundWindow($script:dlg)|Out-Null
  [W32DlgSubmit]::SetFocus($file)|Out-Null
  [System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
  Start-Sleep -Seconds 3
}
$still=[W32DlgSubmit]::IsWindow($script:dlg)
if($still){throw 'Open dialog still present after IDOK/Enter'}

Start-Sleep -Seconds 6
[pscustomobject]@{file_field=$current;dialog_closed=$true;image_exists=(Test-Path -LiteralPath $path)}|ConvertTo-Json -Compress
